{'content': '// Print-in-Place Planetary Gearbox
// Designed for PETG, 0.4mm nozzle, 0.1mm layer height
// All parts print together and rotate freely after printing

// === PARAMETERS ===

// Clearances for print-in-place (PETG with 0.4mm nozzle)
clearance_xy = 0.3;      // Horizontal clearance between moving parts
clearance_z = 0.2;       // Vertical clearance for captured parts

// Gear parameters
module_size = 2.0;       // Gear module (tooth size)
pressure_angle = 20;     // Standard pressure angle
gear_height = 10;        // Height of gear teeth

// Tooth counts (must satisfy: ring = sun + 2*planet for proper meshing)
sun_teeth = 12;
planet_teeth = 9;
ring_teeth = 30;         // 12 + 2*9 = 30 ✓

// Number of planet gears
num_planets = 3;

// Derived dimensions
sun_pitch_r = (module_size * sun_teeth) / 2;
planet_pitch_r = (module_size * planet_teeth) / 2;
ring_pitch_r = (module_size * ring_teeth) / 2;
planet_orbit_r = sun_pitch_r + planet_pitch_r;

// Ring gear outer dimensions
ring_outer_r = ring_pitch_r + module_size * 1.5 + 5;
ring_wall = 4;

// Carrier dimensions
carrier_thickness = 4;
carrier_hub_r = sun_pitch_r - module_size - 1;
carrier_outer_r = planet_orbit_r + planet_pitch_r/2;

// Total height
base_height = 3;
total_height = base_height + gear_height + carrier_thickness + clearance_z * 2;

// === INVOLUTE GEAR FUNCTIONS ===

function involute(base_r, angle) = [
    base_r * (cos(angle) + angle * PI/180 * sin(angle)),
    base_r * (sin(angle) - angle * PI/180 * cos(angle))
];

function involute_angle(base_r, r) = 
    sqrt(r*r - base_r*base_r) / base_r * 180/PI;

// === GEAR TOOTH MODULE ===
module gear_tooth_2d(pitch_r, base_r, outer_r, root_r, tooth_angle) {
    // Simplified involute tooth profile
    steps = 8;
    start_angle = (base_r < root_r) ? involute_angle(base_r, root_r) : 0;
    end_angle = involute_angle(base_r, outer_r);

    // Generate tooth profile points
    points = concat(
        // Root on one side
        [[root_r * cos(-tooth_angle/4), root_r * sin(-tooth_angle/4)]],
        // Involute up one side
        [for(i = [0:steps]) 
            let(angle = start_angle + (end_angle - start_angle) * i / steps)
            let(pt = involute(base_r, angle))
            let(rot = -tooth_angle/4 - start_angle)
            [pt[0]*cos(rot) - pt[1]*sin(rot), pt[0]*sin(rot) + pt[1]*cos(rot)]
        ],
        // Tip
        [[outer_r * cos(0), outer_r * sin(0)]],
        // Involute down other side (mirrored)
        [for(i = [steps:-1:0]) 
            let(angle = start_angle + (end_angle - start_angle) * i / steps)
            let(pt = involute(base_r, angle))
            let(rot = tooth_angle/4 + start_angle)
            [pt[0]*cos(rot) + pt[1]*sin(rot), -pt[0]*sin(rot) + pt[1]*cos(rot)]
        ],
        // Root on other side
        [[root_r * cos(tooth_angle/4), root_r * sin(tooth_angle/4)]]
    );

    polygon(points);
}

// === EXTERNAL GEAR MODULE ===
module external_gear_2d(teeth, mod, pa, clearance=0) {
    pitch_r = mod * teeth / 2;
    base_r = pitch_r * cos(pa);
    outer_r = pitch_r + mod - clearance;
    root_r = pitch_r - 1.25 * mod;
    tooth_angle = 360 / teeth;

    union() {
        circle(r = root_r, $fn = teeth * 4);
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
                gear_tooth_2d(pitch_r, base_r, outer_r, root_r, tooth_angle);
        }
    }
}

// === INTERNAL GEAR MODULE ===
module internal_gear_2d(teeth, mod, pa, clearance=0) {
    pitch_r = mod * teeth / 2;
    base_r = pitch_r * cos(pa);
    inner_r = pitch_r - mod + clearance;  // Root of internal gear (where external gear tips go)
    tip_r = pitch_r + 1.25 * mod;         // Tips of internal gear teeth
    tooth_angle = 360 / teeth;

    difference() {
        circle(r = tip_r + 2, $fn = teeth * 4);

        // Remove material for teeth (inverse of external gear)
        union() {
            circle(r = inner_r, $fn = teeth * 4);
            for(i = [0:teeth-1]) {
                rotate([0, 0, i * tooth_angle + tooth_angle/2])
                    gear_tooth_2d(pitch_r, base_r, tip_r, inner_r, tooth_angle);
            }
        }
    }
}

// === SUN GEAR ===
module sun_gear() {
    // Gear portion
    linear_extrude(height = gear_height)
        external_gear_2d(sun_teeth, module_size, pressure_angle, clearance_xy/2);

    // Central shaft extending up for handle
    shaft_r = sun_pitch_r - module_size - 2;
    translate([0, 0, gear_height])
        cylinder(r = shaft_r, h = carrier_thickness + clearance_z * 2 + 5, $fn = 32);

    // Handle on top
    translate([0, 0, gear_height + carrier_thickness + clearance_z * 2 + 5])
        cylinder(r = shaft_r + 4, h = 3, $fn = 6);  // Hex handle

    // Base hub
    translate([0, 0, -base_height])
        cylinder(r = shaft_r, h = base_height, $fn = 32);
}

// === PLANET GEAR ===
module planet_gear() {
    difference() {
        union() {
            // Main gear body
            linear_extrude(height = gear_height)
                external_gear_2d(planet_teeth, module_size, pressure_angle, clearance_xy/2);
        }

        // Axle hole (for carrier pin)
        translate([0, 0, -0.1])
            cylinder(r = 2 + clearance_xy, h = gear_height + 0.2, $fn = 24);
    }
}

// === PLANET CARRIER ===
module carrier() {
    pin_r = 2;
    pin_h = gear_height - clearance_z * 2;

    // Lower carrier plate (below gears)
    translate([0, 0, -base_height + clearance_z]) {
        difference() {
            cylinder(r = carrier_outer_r, h = base_height - clearance_z * 2, $fn = 64);

            // Center hole for sun shaft
            translate([0, 0, -0.1])
                cylinder(r = sun_pitch_r - module_size - 2 + clearance_xy, 
                        h = base_height + 0.2, $fn = 32);
        }
    }

    // Planet axle pins (print with gears around them)
    for(i = [0:num_planets-1]) {
        angle = i * 360 / num_planets;
        rotate([0, 0, angle])
            translate([planet_orbit_r, 0, clearance_z]) {
                cylinder(r = pin_r, h = pin_h, $fn = 24);
            }
    }

    // Upper carrier plate (above gears)
    translate([0, 0, gear_height + clearance_z]) {
        difference() {
            cylinder(r = carrier_outer_r, h = carrier_thickness, $fn = 64);

            // Center hole for sun shaft
            translate([0, 0, -0.1])
                cylinder(r = sun_pitch_r - module_size - 2 + clearance_xy, 
                        h = carrier_thickness + 0.2, $fn = 32);

            // Planet pin holes (pins connect to lower carrier)
            for(i = [0:num_planets-1]) {
                angle = i * 360 / num_planets;
                rotate([0, 0, angle])
                    translate([planet_orbit_r, 0, -0.1])
                        cylinder(r = pin_r + clearance_xy, h = carrier_thickness + 0.2, $fn = 24);
            }
        }
    }

    // Carrier output hub on top
    translate([0, 0, gear_height + clearance_z + carrier_thickness]) {
        difference() {
            cylinder(r = carrier_outer_r - 5, h = 5, $fn = 64);
            translate([0, 0, -0.1])
                cylinder(r = sun_pitch_r - module_size - 2 + clearance_xy, 
                        h = 5.2, $fn = 32);
        }
    }
}

// === RING GEAR (FIXED HOUSING) ===
module ring_gear() {
    inner_tooth_r = ring_pitch_r - module_size;

    difference() {
        // Outer cylinder
        cylinder(r = ring_outer_r, h = total_height, $fn = 64);

        // Internal gear teeth cavity
        translate([0, 0, base_height])
            linear_extrude(height = gear_height + 0.1)
                difference() {
                    circle(r = ring_pitch_r + module_size * 1.5, $fn = 64);
                    internal_gear_2d(ring_teeth, module_size, pressure_angle, clearance_xy/2);
                }

        // Lower cavity for carrier base
        translate([0, 0, -0.1])
            cylinder(r = carrier_outer_r + clearance_xy, h = base_height + 0.1, $fn = 64);

        // Upper cavity for carrier top and output
        translate([0, 0, base_height + gear_height])
            cylinder(r = carrier_outer_r + clearance_xy, 
                    h = total_height - base_height - gear_height + 0.1, $fn = 64);

        // Center hole through everything for sun shaft and carrier hub
        translate([0, 0, -0.1])
            cylinder(r = carrier_outer_r - 5 + clearance_xy, h = total_height + 0.2, $fn = 64);
    }

    // Add base flange for stability
    translate([0, 0, -2])
        difference() {
            cylinder(r = ring_outer_r + 5, h = 2, $fn = 64);
            translate([0, 0, -0.1])
                cylinder(r = carrier_outer_r + clearance_xy, h = 2.2, $fn = 64);
        }
}

// === ASSEMBLY ===
module assembly() {
    color("orange") ring_gear();

    color("yellow") 
        translate([0, 0, base_height])
            sun_gear();

    color("lime")
        translate([0, 0, base_height])
            carrier();

    color("cyan")
        for(i = [0:num_planets-1]) {
            angle = i * 360 / num_planets;
            rotate([0, 0, angle])
                translate([planet_orbit_r, 0, base_height])
                    planet_gear();
        }
}

// Render the assembly
assembly();
'}

{'content': '// Print-in-Place Planetary Gearbox
// Designed for PETG, 0.4mm nozzle, 0.1mm layer height
// All parts print together and rotate freely after printing

// === PARAMETERS ===

// Clearances for print-in-place (PETG with 0.4mm nozzle)
clearance_xy = 0.35;     // Horizontal clearance between moving parts
clearance_z = 0.25;      // Vertical clearance for captured parts

// Gear parameters
module_size = 2.0;       // Gear module (tooth size)
pressure_angle = 20;     // Standard pressure angle
gear_height = 12;        // Height of gear teeth

// Tooth counts (must satisfy: ring = sun + 2*planet for proper meshing)
sun_teeth = 12;
planet_teeth = 9;
ring_teeth = 30;         // 12 + 2*9 = 30 ✓

// Number of planet gears
num_planets = 3;

// Derived dimensions
sun_pitch_r = (module_size * sun_teeth) / 2;
planet_pitch_r = (module_size * planet_teeth) / 2;
ring_pitch_r = (module_size * ring_teeth) / 2;
planet_orbit_r = sun_pitch_r + planet_pitch_r;

// Ring gear outer dimensions
ring_outer_r = ring_pitch_r + module_size * 2 + 3;

// Carrier dimensions
carrier_hub_r = 4;
carrier_outer_r = planet_orbit_r + planet_pitch_r/2 + 2;
carrier_thickness = 3;

// Total height
base_height = 4;
top_space = carrier_thickness + 2;
total_height = base_height + gear_height + top_space;

// Planet pin dimensions
pin_r = 2.5;

$fn = 48;

// === SIMPLIFIED GEAR TOOTH PROFILE ===
// Using a simplified but functional tooth profile

module gear_tooth_profile(pitch_r, num_teeth, is_internal = false, backlash = 0) {
    // Gear geometry
    addendum = module_size;
    dedendum = 1.25 * module_size;

    outer_r = pitch_r + addendum;
    root_r = pitch_r - dedendum;
    base_r = pitch_r * cos(pressure_angle);

    // Tooth thickness at pitch circle (with backlash)
    tooth_thickness = (PI * module_size / 2) - backlash;
    tooth_half_angle = (tooth_thickness / pitch_r) * 180 / PI / 2;

    if (!is_internal) {
        // External gear tooth
        hull() {
            // Root
            rotate([0, 0, -tooth_half_angle * 0.9])
                translate([root_r, 0, 0])
                    circle(r = 0.3);
            rotate([0, 0, tooth_half_angle * 0.9])
                translate([root_r, 0, 0])
                    circle(r = 0.3);
            // Tip (narrower)
            rotate([0, 0, -tooth_half_angle * 0.4])
                translate([outer_r - 0.3, 0, 0])
                    circle(r = 0.3);
            rotate([0, 0, tooth_half_angle * 0.4])
                translate([outer_r - 0.3, 0, 0])
                    circle(r = 0.3);
        }
    }
}

// === EXTERNAL GEAR ===
module external_gear_2d(teeth, backlash = 0) {
    pitch_r = module_size * teeth / 2;
    addendum = module_size;
    dedendum = 1.25 * module_size;
    outer_r = pitch_r + addendum - backlash/2;
    root_r = pitch_r - dedendum;
    base_r = pitch_r * cos(pressure_angle);

    // Tooth dimensions
    tooth_angle = 360 / teeth;
    tooth_thickness = (PI * module_size / 2) - backlash;
    tooth_half_angle_pitch = (tooth_thickness / pitch_r) * 180 / PI / 2;

    // Tip half angle (narrower at top)
    tip_half_angle = tooth_half_angle_pitch * 0.5;

    union() {
        // Root circle
        circle(r = root_r);

        // Teeth
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
                polygon([
                    [root_r * cos(-tooth_half_angle_pitch), root_r * sin(-tooth_half_angle_pitch)],
                    [base_r * cos(-tooth_half_angle_pitch * 0.95), base_r * sin(-tooth_half_angle_pitch * 0.95)],
                    [pitch_r * cos(-tooth_half_angle_pitch * 0.8), pitch_r * sin(-tooth_half_angle_pitch * 0.8)],
                    [outer_r * cos(-tip_half_angle), outer_r * sin(-tip_half_angle)],
                    [outer_r * cos(tip_half_angle), outer_r * sin(tip_half_angle)],
                    [pitch_r * cos(tooth_half_angle_pitch * 0.8), pitch_r * sin(tooth_half_angle_pitch * 0.8)],
                    [base_r * cos(tooth_half_angle_pitch * 0.95), base_r * sin(tooth_half_angle_pitch * 0.95)],
                    [root_r * cos(tooth_half_angle_pitch), root_r * sin(tooth_half_angle_pitch)]
                ]);
        }
    }
}

// === INTERNAL GEAR (Ring) ===
module internal_gear_2d(teeth, backlash = 0) {
    pitch_r = module_size * teeth / 2;
    // For internal gears, addendum and dedendum are swapped
    inner_r = pitch_r - module_size + backlash/2;  // Where external tips reach
    tip_r = pitch_r + 1.25 * module_size;          // Internal gear tooth tips

    tooth_angle = 360 / teeth;
    tooth_thickness = (PI * module_size / 2) - backlash;
    tooth_half_angle_pitch = (tooth_thickness / pitch_r) * 180 / PI / 2;

    // Space between teeth (where external teeth go)
    space_half_angle = (tooth_angle/2) - tooth_half_angle_pitch;

    difference() {
        circle(r = tip_r + 5);

        // Central opening with tooth spaces
        union() {
            circle(r = inner_r);

            // Tooth spaces (gaps for external gear teeth)
            for(i = [0:teeth-1]) {
                rotate([0, 0, i * tooth_angle])
                    polygon([
                        [inner_r * 0.95 * cos(-space_half_angle), inner_r * 0.95 * sin(-space_half_angle)],
                        [(pitch_r - module_size*0.3) * cos(-space_half_angle * 0.9), (pitch_r - module_size*0.3) * sin(-space_half_angle * 0.9)],
                        [pitch_r * cos(-space_half_angle * 0.7), pitch_r * sin(-space_half_angle * 0.7)],
                        [(pitch_r + module_size*0.5) * cos(-space_half_angle * 0.3), (pitch_r + module_size*0.5) * sin(-space_half_angle * 0.3)],
                        [(pitch_r + module_size*0.5) * cos(space_half_angle * 0.3), (pitch_r + module_size*0.5) * sin(space_half_angle * 0.3)],
                        [pitch_r * cos(space_half_angle * 0.7), pitch_r * sin(space_half_angle * 0.7)],
                        [(pitch_r - module_size*0.3) * cos(space_half_angle * 0.9), (pitch_r - module_size*0.3) * sin(space_half_angle * 0.9)],
                        [inner_r * 0.95 * cos(space_half_angle), inner_r * 0.95 * sin(space_half_angle)]
                    ]);
            }
        }
    }
}

// === SUN GEAR ===
module sun_gear() {
    sun_outer_r = sun_pitch_r + module_size;
    shaft_r = 4;

    difference() {
        union() {
            // Gear teeth
            linear_extrude(height = gear_height)
                external_gear_2d(sun_teeth, clearance_xy);

            // Shaft going up through carrier
            translate([0, 0, gear_height])
                cylinder(r = shaft_r, h = top_space + 3);

            // Hex handle on top
            translate([0, 0, gear_height + top_space + 3])
                cylinder(r = shaft_r + 5, h = 4, $fn = 6);

            // Shaft going down
            translate([0, 0, -base_height + clearance_z])
                cylinder(r = shaft_r, h = base_height - clearance_z);
        }

        // Optional center hole for weight reduction
        translate([0, 0, -base_height])
            cylinder(r = 1.5, h = gear_height + base_height + top_space + 10);
    }
}

// === PLANET GEAR ===
module planet_gear() {
    planet_outer_r = planet_pitch_r + module_size;

    difference() {
        // Gear body
        linear_extrude(height = gear_height - clearance_z * 2)
            external_gear_2d(planet_teeth, clearance_xy);

        // Center hole for carrier pin
        translate([0, 0, -0.1])
            cylinder(r = pin_r + clearance_xy, h = gear_height + 0.2);
    }
}

// === CARRIER ===
module carrier() {
    // Bottom plate (prints in base cavity)
    translate([0, 0, -base_height + clearance_z]) {
        difference() {
            // Main disc
            cylinder(r = carrier_outer_r, h = base_height - clearance_z * 2);

            // Center hole for sun shaft
            translate([0, 0, -0.1])
                cylinder(r = 4 + clearance_xy, h = base_height);

            // Weight reduction holes
            for(i = [0:num_planets-1]) {
                angle = i * 360 / num_planets + 60;
                rotate([0, 0, angle])
                    translate([planet_orbit_r * 0.5, 0, -0.1])
                        cylinder(r = 4, h = base_height);
            }
        }
    }

    // Planet pins
    for(i = [0:num_planets-1]) {
        angle = i * 360 / num_planets;
        rotate([0, 0, angle])
            translate([planet_orbit_r, 0, clearance_z])
                cylinder(r = pin_r, h = gear_height - clearance_z * 2);
    }

    // Top plate
    translate([0, 0, gear_height]) {
        difference() {
            union() {
                // Main disc
                cylinder(r = carrier_outer_r, h = carrier_thickness);

                // Output hub
                translate([0, 0, carrier_thickness])
                    difference() {
                        cylinder(r = carrier_outer_r - 3, h = 4);
                        // Hex socket for output
                        translate([0, 0, 1])
                            cylinder(r = 6, h = 4, $fn = 6);
                    }
            }

            // Center hole for sun shaft
            translate([0, 0, -0.1])
                cylinder(r = 4 + clearance_xy, h = carrier_thickness + 10);

            // Pin connection holes (pins from bottom connect here)
            for(i = [0:num_planets-1]) {
                angle = i * 360 / num_planets;
                rotate([0, 0, angle])
                    translate([planet_orbit_r, 0, -0.1])
                        cylinder(r = pin_r + 0.1, h = carrier_thickness + 0.2);
            }
        }
    }

    // Connecting posts between bottom and top plates (outside gear mesh zone)
    post_r = 2.5;
    for(i = [0:num_planets-1]) {
        angle = i * 360 / num_planets + 60;  // Offset from planets
        rotate([0, 0, angle])
            translate([carrier_outer_r - 3, 0, -base_height + clearance_z])
                cylinder(r = post_r, h = gear_height + base_height + carrier_thickness - clearance_z * 2);
    }
}

// === RING GEAR HOUSING ===
module ring_housing() {
    ring_inner_r = ring_pitch_r - 1.25 * module_size;

    difference() {
        union() {
            // Main body
            cylinder(r = ring_outer_r, h = total_height);

            // Base flange
            translate([0, 0, -3])
                cylinder(r = ring_outer_r + 8, h = 3);

            // Mounting tabs
            for(i = [0:3]) {
                rotate([0, 0, i * 90 + 45])
                    translate([ring_outer_r + 4, 0, -3])
                        cylinder(r = 6, h = 3);
            }
        }

        // Internal gear teeth
        translate([0, 0, base_height - 0.1])
            linear_extrude(height = gear_height + 0.2)
                difference() {
                    circle(r = ring_pitch_r + module_size * 2);
                    internal_gear_2d(ring_teeth, clearance_xy);
                }

        // Bottom cavity for carrier base
        translate([0, 0, -0.1])
            cylinder(r = carrier_outer_r + clearance_xy, h = base_height + 0.1);

        // Top cavity for carrier top and output
        translate([0, 0, base_height + gear_height])
            cylinder(r = carrier_outer_r + clearance_xy, h = top_space + 0.1);

        // Center opening for sun shaft and carrier output
        translate([0, 0, base_height + gear_height + carrier_thickness])
            cylinder(r = carrier_outer_r - 3 + clearance_xy, h = 20);

        // Bottom center opening
        translate([0, 0, -5])
            cylinder(r = carrier_outer_r + clearance_xy, h = 5);

        // Mounting holes
        for(i = [0:3]) {
            rotate([0, 0, i * 90 + 45])
                translate([ring_outer_r + 4, 0, -5])
                    cylinder(r = 2, h = 10);
        }
    }
}

// === COMPLETE ASSEMBLY ===
module assembly() {
    // Ring gear housing (stationary, orange)
    color("orange", 0.8) 
        ring_housing();

    // Sun gear (input, yellow)
    color("gold") 
        translate([0, 0, base_height])
            sun_gear();

    // Carrier (output, green)
    color("limegreen") 
        translate([0, 0, base_height])
            carrier();

    // Planet gears (cyan)
    color("deepskyblue")
        for(i = [0:num_planets-1]) {
            angle = i * 360 / num_planets;
            rotate([0, 0, angle])
                translate([planet_orbit_r, 0, base_height + clearance_z])
                    planet_gear();
        }
}

// Render
assembly();

// Debug: uncomment to see cross section
// difference() {
//     assembly();
//     translate([0, -100, -10]) cube([200, 200, 200]);
// }
'}

