    pitch_r = module_size * teeth / 2;
    addendum = module_size;
    dedendum = 1.25 * module_size;
    outer_r = pitch_r + addendum - backlash/2;
    root_r = pitch_r - dedendum;
    base_r = pitch_r * cos(pressure_angle);

    // Tooth dimensions
    tooth_angle = 360 / teeth;
    tooth_thickness = (PI * module_size / 2) - backlash;
    tooth_half_angle_pitch = (tooth_thickness / pitch_r) * 180 / PI / 2;

    // Tip half angle (narrower at top)
    tip_half_angle = tooth_half_angle_pitch * 0.5;

    union() {
        // Root circle
        circle(r = root_r);

        // Teeth
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
                polygon([
                    [root_r * cos(-tooth_half_angle_pitch), root_r * sin(-tooth_half_angle_pitch)],
                    [base_r * cos(-tooth_half_angle_pitch * 0.95), base_r * sin(-tooth_half_angle_pitch * 0.95)],
                    [pitch_r * cos(-tooth_half_angle_pitch * 0.8), pitch_r * sin(-tooth_half_angle_pitch * 0.8)],
                    [outer_r * cos(-tip_half_angle), outer_r * sin(-tip_half_angle)],
                    [outer_r * cos(tip_half_angle), outer_r * sin(tip_half_angle)],
                    [pitch_r * cos(tooth_half_angle_pitch * 0.8), pitch_r * sin(tooth_half_angle_pitch * 0.8)],
                    [base_r * cos(tooth_half_angle_pitch * 0.95), base_r * sin(tooth_half_angle_pitch * 0.95)],
                    [root_r * cos(tooth_half_angle_pitch), root_r * sin(tooth_half_angle_pitch)]
                ]);
        }
    }
}

// === INTERNAL GEAR (Ring) ===
module internal_gear_2d(teeth, backlash = 0) {
    pitch_r = module_size * teeth / 2;
    // For internal gears, addendum and dedendum are swapped
    inner_r = pitch_r - module_size + backlash/2;  // Where external tips reach
    tip_r = pitch_r + 1.25 * module_size;          // Internal gear tooth tips

    tooth_angle = 360 / teeth;
    tooth_thickness = (PI * module_size / 2) - backlash;
    tooth_half_angle_pitch = (tooth_thickness / pitch_r) * 180 / PI / 2;

    // Space between teeth (where external teeth go)
    space_half_angle = (tooth_angle/2) - tooth_half_angle_pitch;

    difference() {
        circle(r = tip_r + 5);

        // Central opening with tooth spaces
        union() {
            circle(r = inner_r);

            // Tooth spaces (gaps for external gear teeth)
            for(i = [0:teeth-1]) {
                rotate([0, 0, i * tooth_angle])
                    polygon([
                        [inner_r * 0.95 * cos(-space_half_angle), inner_r * 0.95 * sin(-space_half_angle)],
                        [(pitch_r - module_size*0.3) * cos(-space_half_angle * 0.9), (pitch_r - module_size*0.3) * sin(-space_half_angle * 0.9)],
                        [pitch_r * cos(-space_half_angle * 0.7), pitch_r * sin(-space_half_angle * 0.7)],
                        [(pitch_r + module_size*0.5) * cos(-space_half_angle * 0.3), (pitch_r + module_size*0.5) * sin(-space_half_angle * 0.3)],
                        [(pitch_r + module_size*0.5) * cos(space_half_angle * 0.3), (pitch_r + module_size*0.5) * sin(space_half_angle * 0.3)],
                        [pitch_r * cos(space_half_angle * 0.7), pitch_r * sin(space_half_angle * 0.7)],
                        [(pitch_r - module_size*0.3) * cos(space_half_angle * 0.9), (pitch_r - module_size*0.3) * sin(space_half_angle * 0.9)],
                        [inner_r * 0.95 * cos(space_half_angle), inner_r * 0.95 * sin(space_half_angle)]
                    ]);
            }
        }
    }
}

// === SUN GEAR ===
module sun_gear() {
    sun_outer_r = sun_pitch_r + module_size;
    shaft_r = 4;

    difference() {
        union() {
            // Gear teeth
            linear_extrude(height = gear_height)
                external_gear_2d(sun_teeth, clearance_xy);

            // Shaft going up through carrier
            translate([0, 0, gear_height])
                cylinder(r = shaft_r, h = top_space + 3);

            // Hex handle on top
            translate([0, 0, gear_height + top_space + 3])
                cylinder(r = shaft_r + 5, h = 4, $fn = 6);

            // Shaft going down
            translate([0, 0, -base_height + clearance_z])
                cylinder(r = shaft_r, h = base_height - clearance_z);
        }

        // Optional center hole for weight reduction
        translate([0, 0, -base_height])
            cylinder(r = 1.5, h = gear_height + base_height + top_space + 10);
    }
}

// === PLANET GEAR ===
module planet_gear() {
    planet_outer_r = planet_pitch_r + module_size;

    difference() {
        // Gear body
        linear_extrude(height = gear_height - clearance_z * 2)
            external_gear_2d(planet_teeth, clearance_xy);

        // Center hole for carrier pin
        translate([0, 0, -0.1])
            cylinder(r = pin_r + clearance_xy, h = gear_height + 0.2);
    }
}

// === CARRIER ===
module carrier() {
    // Bottom plate (prints in base cavity)
    translate([0, 0, -base_height + clearance_z]) {
        difference() {
            // Main disc
            cylinder(r = carrier_outer_r, h = base_height - clearance_z * 2);

            // Center hole for sun shaft
            translate([0, 0, -0.1])
                cylinder(r = 4 + clearance_xy, h = base_height);

            // Weight reduction holes
            for(i = [0:num_planets-1]) {
                angle = i * 360 / num_planets + 60;
                rotate([0, 0, angle])
                    translate([planet_orbit_r * 0.5, 0, -0.1])
                        cylinder(r = 4, h = base_height);
            }
        }
    }

    // Planet pins
    for(i = [0:num_planets-1]) {
        angle = i * 360 / num_planets;
        rotate([0, 0, angle])
            translate([planet_orbit_r, 0, clearance_z])
                cylinder(r = pin_r, h = gear_height - clearance_z * 2);
    }

    // Top plate
    translate([0, 0, gear_height]) {
        difference() {
            union() {
                // Main disc
                cylinder(r = carrier_outer_r, h = carrier_thickness);

                // Output hub
                translate([0, 0, carrier_thickness])
                    difference() {
                        cylinder(r = carrier_outer_r - 3, h = 4);
                        // Hex socket for output
                        translate([0, 0, 1])
                            cylinder(r = 6, h = 4, $fn = 6);
                    }
            }

            // Center hole for sun shaft
            translate([0, 0, -0.1])
                cylinder(r = 4 + clearance_xy, h = carrier_thickness + 10);

            // Pin connection holes (pins from bottom connect here)
            for(i = [0:num_planets-1]) {
                angle = i * 360 / num_planets;
                rotate([0, 0, angle])
                    translate([planet_orbit_r, 0, -0.1])
                        cylinder(r = pin_r + 0.1, h = carrier_thickness + 0.2);
            }
        }
    }

    // Connecting posts between bottom and top plates (outside gear mesh zone)
    post_r = 2.5;
    for(i = [0:num_planets-1]) {
        angle = i * 360 / num_planets + 60;  // Offset from planets
        rotate([0, 0, angle])
            translate([carrier_outer_r - 3, 0, -base_height + clearance_z])
                cylinder(r = post_r, h = gear_height + base_height + carrier_thickness - clearance_z * 2);
    }
}

// === RING GEAR HOUSING ===
module ring_housing() {
    ring_inner_r = ring_pitch_r - 1.25 * module_size;

    difference() {
        union() {
            // Main body
            cylinder(r = ring_outer_r, h = total_height);

            // Base flange
            translate([0, 0, -3])
                cylinder(r = ring_outer_r + 8, h = 3);

            // Mounting tabs
            for(i = [0:3]) {
                rotate([0, 0, i * 90 + 45])
                    translate([ring_outer_r + 4, 0, -3])
                        cylinder(r = 6, h = 3);
            }
        }

        // Internal gear teeth
        translate([0, 0, base_height - 0.1])
            linear_extrude(height = gear_height + 0.2)
                difference() {
                    circle(r = ring_pitch_r + module_size * 2);
                    internal_gear_2d(ring_teeth, clearance_xy);
                }

        // Bottom cavity for carrier base
        translate([0, 0, -0.1])
            cylinder(r = carrier_outer_r + clearance_xy, h = base_height + 0.1);

        // Top cavity for carrier top and output
        translate([0, 0, base_height + gear_height])
            cylinder(r = carrier_outer_r + clearance_xy, h = top_space + 0.1);

        // Center opening for sun shaft and carrier output
        translate([0, 0, base_height + gear_height + carrier_thickness])
            cylinder(r = carrier_outer_r - 3 + clearance_xy, h = 20);

        // Bottom center opening
        translate([0, 0, -5])
            cylinder(r = carrier_outer_r + clearance_xy, h = 5);

        // Mounting holes
        for(i = [0:3]) {
            rotate([0, 0, i * 90 + 45])
                translate([ring_outer_r + 4, 0, -5])
                    cylinder(r = 2, h = 10);
        }
    }
}

// === COMPLETE ASSEMBLY ===
module assembly() {
    // Ring gear housing (stationary, orange)
    color("orange", 0.8) 
        ring_housing();

    // Sun gear (input, yellow)
    color("gold") 
        translate([0, 0, base_height])
            sun_gear();

    // Carrier (output, green)
    color("limegreen") 
        translate([0, 0, base_height])
            carrier();

    // Planet gears (cyan)
    color("deepskyblue")
        for(i = [0:num_planets-1]) {
            angle = i * 360 / num_planets;
            rotate([0, 0, angle])
                translate([planet_orbit_r, 0, base_height + clearance_z])
                    planet_gear();
        }
}

// Cross section view for verification
module cross_section() {
    difference() {
        assembly();
        translate([0, -100, -10]) cube([200, 200, 200]);
    }
}

// Render cross section to verify clearances
cross_section();
'}

{'content': '// Print-in-Place Planetary Gearbox
// Designed for PETG, 0.4mm nozzle, 0.1mm layer height
// All parts print together and rotate freely after printing

// === PARAMETERS ===

// Clearances for print-in-place (PETG with 0.4mm nozzle)
clearance_xy = 0.4;      // Horizontal clearance between moving parts
clearance_z = 0.3;       // Vertical clearance for captured parts

// Gear parameters
module_size = 2.5;       // Gear module (tooth size) - larger for better printing
pressure_angle = 20;     // Standard pressure angle
gear_height = 10;        // Height of gear teeth

// Tooth counts (must satisfy: ring = sun + 2*planet for proper meshing)
sun_teeth = 10;
planet_teeth = 8;
ring_teeth = 26;         // 10 + 2*8 = 26 ✓

// Number of planet gears
num_planets = 3;

// Derived dimensions
sun_pitch_r = (module_size * sun_teeth) / 2;
planet_pitch_r = (module_size * planet_teeth) / 2;
ring_pitch_r = (module_size * ring_teeth) / 2;
planet_orbit_r = sun_pitch_r + planet_pitch_r;

// Ring gear outer dimensions
ring_outer_r = ring_pitch_r + module_size * 2 + 4;

// Carrier dimensions
carrier_outer_r = ring_pitch_r - module_size * 1.5 - clearance_xy;

// Total heights
base_thickness = 3;       // Carrier bottom plate
top_thickness = 3;        // Carrier top plate
total_height = base_thickness + gear_height + top_thickness;

// Pin dimensions
pin_r = 3;

$fn = 64;

// === EXTERNAL GEAR WITH PROPER INVOLUTE ===
module external_gear_2d(teeth, backlash = 0) {
    pitch_r = module_size * teeth / 2;
    addendum = module_size * 1.0;
    dedendum = module_size * 1.25;
    outer_r = pitch_r + addendum - backlash/2;
    root_r = pitch_r - dedendum;
    base_r = pitch_r * cos(pressure_angle);

    tooth_angle = 360 / teeth;

    // Approximate involute with circular arcs
    // Tooth thickness at pitch circle
    tooth_arc = PI * module_size / 2 - backlash;
    half_tooth_angle = (tooth_arc / pitch_r) * 180 / PI / 2;

    union() {
        circle(r = root_r, $fn = teeth * 6);

        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle]) {
                // Simplified tooth shape - trapezoidal approximation
                polygon([
                    // Root points
                    [root_r * cos(-half_tooth_angle * 1.1), root_r * sin(-half_tooth_angle * 1.1)],
                    // Flank points 
                    [pitch_r * cos(-half_tooth_angle * 0.85), pitch_r * sin(-half_tooth_angle * 0.85)],
                    // Tip points (narrower)
                    [outer_r * cos(-half_tooth_angle * 0.45), outer_r * sin(-half_tooth_angle * 0.45)],
                    [outer_r * cos(half_tooth_angle * 0.45), outer_r * sin(half_tooth_angle * 0.45)],
                    // Flank points
                    [pitch_r * cos(half_tooth_angle * 0.85), pitch_r * sin(half_tooth_angle * 0.85)],
                    // Root points
                    [root_r * cos(half_tooth_angle * 1.1), root_r * sin(half_tooth_angle * 1.1)]
                ]);
            }
        }
    }
}

// === INTERNAL GEAR (Ring) ===
module internal_gear_2d(teeth, backlash = 0) {
    pitch_r = module_size * teeth / 2;
    // For internal gears
    inner_r = pitch_r - module_size * 1.0 + backlash/2;   // Tip clearance
    root_r = pitch_r + module_size * 1.25;                 // Root of internal teeth

    tooth_angle = 360 / teeth;

    // Space for external gear teeth
    space_arc = PI * module_size / 2 + backlash;
    half_space_angle = (space_arc / pitch_r) * 180 / PI / 2;

    difference() {
        circle(r = root_r + 3, $fn = teeth * 6);

        union() {
            circle(r = inner_r, $fn = teeth * 6);

            for(i = [0:teeth-1]) {
                rotate([0, 0, i * tooth_angle]) {
                    // Space between internal teeth
                    polygon([
                        [inner_r * cos(-half_space_angle * 1.1), inner_r * sin(-half_space_angle * 1.1)],
                        [pitch_r * cos(-half_space_angle * 0.85), pitch_r * sin(-half_space_angle * 0.85)],
                        [(pitch_r + module_size * 0.5) * cos(-half_space_angle * 0.4), (pitch_r + module_size * 0.5) * sin(-half_space_angle * 0.4)],
                        [(pitch_r + module_size * 0.5) * cos(half_space_angle * 0.4), (pitch_r + module_size * 0.5) * sin(half_space_angle * 0.4)],
                        [pitch_r * cos(half_space_angle * 0.85), pitch_r * sin(half_space_angle * 0.85)],
                        [inner_r * cos(half_space_angle * 1.1), inner_r * sin(half_space_angle * 1.1)]
                    ]);
                }
            }
        }
    }
}

// === SUN GEAR ===
module sun_gear() {
    shaft_r = sun_pitch_r - module_size * 1.5;

    union() {
        // Main gear body
        linear_extrude(height = gear_height)
            external_gear_2d(sun_teeth, clearance_xy);

        // Lower shaft (captured in ring gear base)
        translate([0, 0, -base_thickness + clearance_z])
            cylinder(r = shaft_r, h = base_thickness - clearance_z);

        // Upper shaft through carrier
        translate([0, 0, gear_height])
            cylinder(r = shaft_r, h = top_thickness + 5);

        // Input handle (hexagonal for grip)
        translate([0, 0, gear_height + top_thickness + 5])
            cylinder(r = shaft_r + 6, h = 5, $fn = 6);
    }
}

// === PLANET GEAR ===
module planet_gear() {
    difference() {
        // Gear body - slightly shorter to allow rotation
        linear_extrude(height = gear_height - clearance_z * 2)
            external_gear_2d(planet_teeth, clearance_xy);

        // Center hole for pin
        translate([0, 0, -0.1])
            cylinder(r = pin_r + clearance_xy, h = gear_height);
    }
}

// === CARRIER (Top and Bottom connected by pins through planets) ===
module carrier() {
    shaft_hole_r = sun_pitch_r - module_size * 1.5 + clearance_xy;

    // Bottom plate
    color("limegreen")
    translate([0, 0, -base_thickness + clearance_z]) {
        difference() {
            cylinder(r = carrier_outer_r, h = base_thickness - clearance_z * 2);
            // Center hole for sun shaft
            translate([0, 0, -0.1])
                cylinder(r = shaft_hole_r, h = base_thickness);
        }
    }

    // Planet pins (extend from bottom plate up through planet gears)
    for(i = [0:num_planets-1]) {
        angle = i * 360 / num_planets;
        rotate([0, 0, angle])
            translate([planet_orbit_r, 0, clearance_z])
                cylinder(r = pin_r, h = gear_height - clearance_z * 2);
    }

    // Top plate
    translate([0, 0, gear_height]) {
        difference() {
            union() {
                // Main plate
                cylinder(r = carrier_outer_r, h = top_thickness - clearance_z);

                // Output hub extending up
                translate([0, 0, top_thickness - clearance_z])
                    cylinder(r = carrier_outer_r - 5, h = 8);
            }

            // Center hole for sun shaft
            translate([0, 0, -0.1])
                cylinder(r = shaft_hole_r, h = top_thickness + 15);

            // Holes for pins to connect
            for(i = [0:num_planets-1]) {
                angle = i * 360 / num_planets;
                rotate([0, 0, angle])
                    translate([planet_orbit_r, 0, -0.1])
                        cylinder(r = pin_r + 0.15, h = top_thickness);
            }

            // Output hex socket
            translate([0, 0, top_thickness + 2])
                cylinder(r = 8, h = 10, $fn = 6);
        }
    }
}

// === RING GEAR HOUSING ===
module ring_housing() {
    inner_gear_r = ring_pitch_r + module_size * 1.5;
    shaft_hole_r = sun_pitch_r - module_size * 1.5 + clearance_xy;
    carrier_cavity_r = carrier_outer_r + clearance_xy;

    difference() {
        union() {
            // Main cylindrical body
            cylinder(r = ring_outer_r, h = total_height);

            // Base flange for stability
            translate([0, 0, -2])
                cylinder(r = ring_outer_r + 10, h = 2);
        }

        // Internal gear teeth
        translate([0, 0, base_thickness - 0.05])
            linear_extrude(height = gear_height + 0.1)
                difference() {
                    circle(r = inner_gear_r);
                    internal_gear_2d(ring_teeth, clearance_xy);
                }

        // Bottom cavity for carrier base
        translate([0, 0, -0.1])
            cylinder(r = carrier_cavity_r, h = base_thickness + 0.1);

        // Top cavity for carrier top
        translate([0, 0, base_thickness + gear_height])
            cylinder(r = carrier_cavity_r, h = top_thickness + 0.1);

        // Output opening (top)
        translate([0, 0, base_thickness + gear_height + top_thickness - clearance_z])
            cylinder(r = carrier_outer_r - 5 + clearance_xy, h = 10);

        // Sun shaft opening (bottom)
        translate([0, 0, -5])
            cylinder(r = shaft_hole_r + 2, h = 10);

        // Ventilation/break-free slots (helps separate parts after printing)
        for(i = [0:5]) {
            rotate([0, 0, i * 60])
                translate([ring_outer_r - 2, -1, base_thickness])
                    cube([5, 2, gear_height]);
        }
    }
}

// === COMPLETE ASSEMBLY ===
module assembly() {
    // Ring gear housing (orange - stationary)
    color("orange", 0.85) 
        ring_housing();

    // Sun gear (gold - input)
    color("gold") 
        translate([0, 0, base_thickness])
            sun_gear();

    // Carrier (green - output)
    color("limegreen") 
        translate([0, 0, base_thickness])
            carrier();

    // Planet gears (cyan)
    color("deepskyblue")
        for(i = [0:num_planets-1]) {
            angle = i * 360 / num_planets;
            rotate([0, 0, angle])
                translate([planet_orbit_r, 0, base_thickness + clearance_z])
                    planet_gear();
        }
}

// === RENDER ===
assembly();
'}

