// === CARRIER (Top and Bottom connected by pins through planets) ===
module carrier() {
    shaft_hole_r = sun_pitch_r - module_size * 1.5 + clearance_xy;

    // Bottom plate
    translate([0, 0, -base_thickness + clearance_z]) {
        difference() {
            cylinder(r = carrier_outer_r, h = base_thickness - clearance_z * 2);
            // Center hole for sun shaft
            translate([0, 0, -0.1])
                cylinder(r = shaft_hole_r, h = base_thickness);
        }
    }

    // Planet pins (extend from bottom plate up through planet gears)
    for(i = [0:num_planets-1]) {
        angle = i * 360 / num_planets;
        rotate([0, 0, angle])
            translate([planet_orbit_r, 0, clearance_z])
                cylinder(r = pin_r, h = gear_height - clearance_z * 2);
    }

    // Top plate
    translate([0, 0, gear_height]) {
        difference() {
            union() {
                // Main plate
                cylinder(r = carrier_outer_r, h = top_thickness - clearance_z);

                // Output hub extending up
                translate([0, 0, top_thickness - clearance_z])
                    cylinder(r = carrier_outer_r - 5, h = 8);
            }

            // Center hole for sun shaft
            translate([0, 0, -0.1])
                cylinder(r = shaft_hole_r, h = top_thickness + 15);

            // Holes for pins to connect
            for(i = [0:num_planets-1]) {
                angle = i * 360 / num_planets;
                rotate([0, 0, angle])
                    translate([planet_orbit_r, 0, -0.1])
                        cylinder(r = pin_r + 0.15, h = top_thickness);
