    // Ring gear housing (orange - stationary)
    color("orange", 0.85) 
        ring_housing();

    // Sun gear (gold - input)
    color("gold") 
        translate([0, 0, base_thickness])
            sun_gear();

    // Carrier (green - output)
    color("limegreen") 
        translate([0, 0, base_thickness])
            carrier();

